<style id="cdqV2501ApkShareCss">
#cdqApkShareModalV2501 .cdq-v2501-card{
  padding:12px;border:1px solid #31516a;border-radius:12px;background:#0b1f30
}
#cdqApkShareModalV2501 .cdq-v2501-url{
  margin-top:7px;font-size:12px;color:#9fb6c9;overflow-wrap:anywhere;word-break:break-all
}
#cdqApkShareModalV2501 .cdq-v2501-grid{display:grid;gap:11px}
#cdqApkShareModalV2501 input{
  min-height:46px;border:1px solid #35536b;border-radius:10px;background:#0d2233;color:#fff;padding:0 10px
}
#cdqApkShareModalV2501 label{display:grid;gap:5px;font-weight:800;font-size:13px}
#cdqApkShareModalV2501 .cdq-v2501-note{font-size:11.5px;color:#8fa7bb;line-height:1.4}
#cdqAdminApkBoxV2501{
  margin:14px 0 6px;padding:12px;border:1px solid #2a6c8f;border-radius:12px;background:#081b29
}
#cdqAdminApkBoxV2501 strong{display:block;margin-bottom:4px}
#cdqAdminApkBoxV2501 small{display:block;color:#9fb8c8;margin-bottom:10px;line-height:1.35}
#cdqAdminApkButtonV2501{width:100%;min-height:52px}
</style>
<script id="cdqV2501ApkShareJs">
(function(){
'use strict';

const APK_URL='https://raw.githubusercontent.com/jprodrigue86/Rapports--talonnages-CDQ/main/downloads/Balance-CDQ-Android.apk';
const UPDATE_MANIFEST_URL='https://raw.githubusercontent.com/jprodrigue86/Rapports--talonnages-CDQ/main/downloads/android-update.json';

function infoV2501(message){
  try{
    if(typeof afficherMessage==='function'){afficherMessage(String(message||''),true);return;}
  }catch(_){}
}

function directMessageV2501(){
  return 'Installer Balance CDQ Android : '+APK_URL+
    '\n\nCe lien télécharge directement le fichier APK, sans page GitHub ni création de raccourci.';
}

async function copyApkLinkV2501(){
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText){
      await navigator.clipboard.writeText(APK_URL);
      infoV2501('Lien APK direct copié.');
      return;
    }
  }catch(_){}
  try{prompt('Copiez le lien APK direct :',APK_URL);}catch(_){}
}

async function shareApkV2501(){
  const data={
    title:'Installer Balance CDQ Android',
    text:'Télécharger et installer Balance CDQ Android',
    url:APK_URL
  };
  if(navigator.share){
    try{
      await navigator.share(data);
      return;
    }catch(e){
      if(e&&e.name==='AbortError')return;
    }
  }
  await copyApkLinkV2501();
}

function sendEmailV2501(email){
  email=String(email||'').trim();
  const href='mailto:'+encodeURIComponent(email)+
    '?subject='+encodeURIComponent('Installation Balance CDQ Android')+
    '&body='+encodeURIComponent(directMessageV2501());
  location.href=href;
}

function sendSmsV2501(number){
  number=String(number||'').replace(/[^0-9+]/g,'');
  const body=encodeURIComponent(directMessageV2501());
  const ios=/iPad|iPhone|iPod/i.test(navigator.userAgent||'');
  location.href='sms:'+number+(ios?'&body=':'?body=')+body;
}

function openDirectApkV2501(){
  const a=document.createElement('a');
  a.href=APK_URL;
  a.target='_top';
  a.rel='noopener';
  a.style.display='none';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

function runNativeUpdaterV2501(){
  const fallback=APK_URL;
  const intent='intent://check?force=1#Intent;scheme=cdqupdate;package=ca.balancecdq.android;'+
    'S.browser_fallback_url='+encodeURIComponent(fallback)+';end';

  const a=document.createElement('a');
  a.href=intent;
  a.target='_top';
  a.rel='noopener';
  a.style.display='none';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

function makeModalV2501(){
  let o=document.getElementById('cdqApkShareModalV2501');
  if(o)return o;

  o=document.createElement('div');
  o.id='cdqApkShareModalV2501';
  o.className='modal-overlay';
  o.style.display='none';
  o.innerHTML=
    '<div class="modal">'+
      '<h2 class="cdq-modal-title">📲 Installer / partager Balance CDQ</h2>'+
      '<div class="cdq-v19-body"><div class="cdq-v2501-grid">'+
        '<div class="cdq-v2501-card">'+
          '<strong>APK Balance CDQ direct</strong>'+
          '<div class="cdq-v2501-url">'+APK_URL+'</div>'+
        '</div>'+
        '<button type="button" id="cdqApkUpdateNowV2501" class="modal-button" style="min-height:54px">'+
          '⬆️ Installer / mettre à jour / réinstaller cette APK'+
        '</button>'+
        '<button type="button" id="cdqApkShareNativeV2501" class="modal-button" style="min-height:52px">'+
          '📤 Partager via Messenger, Messages, courriel…'+
        '</button>'+
        '<label>Adresse courriel (optionnel)'+
          '<input id="cdqApkShareEmailV2501" type="email" autocomplete="email" placeholder="technicien@exemple.com">'+
        '</label>'+
        '<button type="button" id="cdqApkShareEmailButtonV2501" class="modal-button" style="min-height:48px">'+
          '✉️ Envoyer le lien APK par courriel'+
        '</button>'+
        '<label>Numéro de téléphone (optionnel)'+
          '<input id="cdqApkSharePhoneV2501" type="tel" autocomplete="tel" inputmode="tel" placeholder="819 555-1234">'+
        '</label>'+
        '<button type="button" id="cdqApkShareSmsButtonV2501" class="modal-button" style="min-height:48px">'+
          '💬 Envoyer le lien APK par message texte'+
        '</button>'+
        '<button type="button" id="cdqApkCopyV2501" class="modal-button" style="min-height:48px">'+
          '📋 Copier le lien APK direct'+
        '</button>'+
        '<button type="button" id="cdqApkDownloadV2501" class="modal-button" style="min-height:48px">'+
          '⬇️ Télécharger directement le fichier APK'+
        '</button>'+
        '<div class="cdq-v2501-note">'+
          'Le lien partagé pointe directement vers le fichier .apk le plus récent. '+
          'Pour une future mise à jour Android, le bouton « Installer / mettre à jour » vérifie automatiquement la dernière APK. '+
          'Les mises à jour de scripts continuent séparément avec CDQ Script Manager.'+
        '</div>'+
      '</div></div>'+
      '<div class="modal-buttons">'+
        '<button type="button" class="modal-button cancel-button" id="cdqApkShareCloseV2501">Fermer</button>'+
      '</div>'+
    '</div>';

  document.body.appendChild(o);

  o.querySelector('#cdqApkShareCloseV2501').onclick=function(){o.style.display='none';};
  o.addEventListener('click',function(e){if(e.target===o)o.style.display='none';});

  o.querySelector('#cdqApkUpdateNowV2501').onclick=runNativeUpdaterV2501;
  o.querySelector('#cdqApkShareNativeV2501').onclick=shareApkV2501;
  o.querySelector('#cdqApkShareEmailButtonV2501').onclick=function(){
    sendEmailV2501(o.querySelector('#cdqApkShareEmailV2501').value);
  };
  o.querySelector('#cdqApkShareSmsButtonV2501').onclick=function(){
    sendSmsV2501(o.querySelector('#cdqApkSharePhoneV2501').value);
  };
  o.querySelector('#cdqApkCopyV2501').onclick=copyApkLinkV2501;
  o.querySelector('#cdqApkDownloadV2501').onclick=openDirectApkV2501;

  return o;
}

function openShareV2501(){
  const o=makeModalV2501();
  o.style.display='flex';
  const modal=o.querySelector('.modal');
  if(modal)try{modal.scrollTop=0;}catch(_){}
}

function ensureAdminButtonV2501(){
  const overlay=document.getElementById('adminModalOverlay');
  if(!overlay)return;

  const buttons=Array.from(overlay.querySelectorAll('button'));
  const existing=buttons.find(function(b){
    if(b.id==='cdqAdminApkButtonV2501')return true;
    return /installer\s*\/?.*partager.*balance\s*cdq|installer.*partager.*application/i.test(String(b.textContent||''));
  });

  if(existing){
    existing.id='cdqAdminApkButtonV2501';
    existing.onclick=openShareV2501;
    existing.setAttribute('data-cdq-apk-share-v2501','1');
    return;
  }

  if(document.getElementById('cdqAdminApkBoxV2501'))return;

  const box=document.createElement('div');
  box.id='cdqAdminApkBoxV2501';
  box.innerHTML=
    '<strong>📲 Application Balance CDQ</strong>'+
    '<small>Installer, réinstaller, mettre à jour ou partager directement la dernière APK.</small>'+
    '<button type="button" id="cdqAdminApkButtonV2501" class="modal-button">'+
      'Installer / partager Balance CDQ'+
    '</button>';

  const list=overlay.querySelector('#adminUserList');
  const modalBody=overlay.querySelector('.cdq-modal-body,.modal-body,.admin-modal-body')||overlay.querySelector('.modal');

  if(list&&list.parentNode){
    list.insertAdjacentElement('afterend',box);
  }else if(modalBody){
    const buttonsBar=modalBody.querySelector('.modal-buttons');
    if(buttonsBar)buttonsBar.insertAdjacentElement('beforebegin',box);
    else modalBody.appendChild(box);
  }

  const b=box.querySelector('#cdqAdminApkButtonV2501');
  if(b)b.onclick=openShareV2501;
}

document.addEventListener('click',function(e){
  const b=e.target&&e.target.closest?e.target.closest('#cdqInstallShareSettingsButton,#cdqAdminApkButtonV2501'):null;
  if(!b)return;
  e.preventDefault();
  e.stopImmediatePropagation();
  openShareV2501();
},true);

function bootV2501(){
  try{
    window.cdqOuvrirPartageApplication=openShareV2501;
  }catch(_){}
  ensureAdminButtonV2501();
}

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',function(){
    setTimeout(bootV2501,100);
    setTimeout(bootV2501,700);
  },{once:true});
}else{
  setTimeout(bootV2501,20);
  setTimeout(bootV2501,600);
}
window.addEventListener('load',function(){setTimeout(bootV2501,150);});

try{
  new MutationObserver(function(){
    clearTimeout(window.__cdqV2501AdminTimer);
    window.__cdqV2501AdminTimer=setTimeout(ensureAdminButtonV2501,90);
  }).observe(document.body,{childList:true,subtree:true});
}catch(_){}

window.cdqApkDirectUrlV2501=APK_URL;
window.cdqAndroidUpdateManifestV2501=UPDATE_MANIFEST_URL;
window.cdqOpenApkShareV2501=openShareV2501;
})();
</script>\n
